    "do": "cat > workflows.mjs <<'EOF'\\n// Nova's run for one ticket and the line of VM slots, cut down to what this lab needs.\\nimport {\\n  CancellationScope, condition, continueAsNew, defineQuery, defineSignal,\\n  getExternalWorkflowHandle, proxyActivities, setHandler, workflowInfo,\\n} from '@temporalio/workflow';\\n\\nconst act = proxyActivities({ startToCloseTimeout: '7 days', heartbeatTimeout: '2 minutes' });\\n\\nexport const request = defineSignal('request');\\nexport const release = defineSignal('release');\\nexport const slotGranted = defineSignal('slotGranted');\\nexport const decidePlan = defineSignal('decidePlan');\\nexport const lineQuery = defineQuery('line');\\nexport const statusQuery = defineQuery('status');\\n\\nconst SLOTS = { nova: 3 };\\n\\n// One per agent, ID slots:<agent>. It never ends; it hands out slots in the order they were asked for.\\nexport async function slots(agent, holders = [], waiting = []) {\\n  setHandler(request, (id) => void waiting.push(id));\\n  setHandler(release, (id) => { holders = holders.filter((h) => h !== id); });\\n  setHandler(lineQuery, () => ({ holders, waiting }));\\n  while (workflowInfo().historyLength < 5000) {\\n    await condition(() => waiting.length > 0 && holders.length < (SLOTS[agent] ?? 1));\\n    const holder = waiting.shift();\\n    holders.push(holder);\\n    await getExternalWorkflowHandle(holder).signal(slotGranted);\\n  }\\n  await continueAsNew(agent, holders, waiting);\\n}\\n\\n// Build it: hold one of the agent's slots only while fn runs, and give it back on every path.\\n// 1. register a handler for slotGranted, 2. signal request to slots:<agent> with your workflow ID,\\n// 3. wait until granted, 4. run fn, 5. in finally, signal release (nonCancellable, like the VM release).\\n// For now it holds no slot at all, so every ticket gets a VM at once.\\nexport const withSlot = async (agent, fn) => fn();\\n\\nexport async function ticketToPr(ticket) {\\n  let status = 'Checking';\\n  let decision;\\n  setHandler(statusQuery, () => status);\\n  setHandler(decidePlan, (d) => { decision = d; });\\n\\n  const inSandbox = async (task, size, label) => {\\n    status = 'Waiting for a slot';\\n    return withSlot('nova', async () => {\\n      status = label;\\n      const vm = await act.acquireSandbox(ticket, size);\\n      try {\\n        return await act.workInSandbox(vm, task);\\n      } finally {\\n        await CancellationScope.nonCancellable(() => act.releaseSandbox(vm)); // no VM is ever left behind\\n      }\\n    });\\n  };\\n\\n  await inSandbox(\`plan \${ticket}\`, 'lite', 'Planning');\\n  status = 'Awaiting approval';\\n  await condition(() => decision !== undefined, '3 days'); // no VM and no slot while a person thinks\\n  if (decision !== 'approve') return (status = 'Stopped');\\n  const pr = await inSandbox(\`build \${ticket}\`, 'full', 'Working');\\n  return (status = \`PR open: \${pr}\`);\\n}\\nEOF",
